1	import java.util.List;
2	import java.util.Random;
3	
4	/**
5	 * A class representing shared characteristics of animals.
6	 *
7	 * @version 2016.02.29 (2)
8	 */
9	public abstract class Animal
10	{
11	    // A shared random number generator to control breeding.
12	    private static final Random rand = Randomizer.getRandom();
13	
14	    // Whether the animal is alive or not.
15	    private boolean alive;
16	    // The animal's field.
17	    private Field field;
18	    // The animal's position in the field.
19	    private Location location;
20	    // The animal's hurt level, when > 3 die
21	    private int burn;
22	    // The Deer's gender.
23	    private String gender;
24	
25	    
26	    /**
27	     * Create a new animal at location in field.
28	     * 
29	     * @param field The field currently occupied.
30	     * @param location The location within the field.
31	     */
32	    public Animal(Field field, Location location)
33	    {
34	        alive = true;
35	        this.field = field;
36	        setLocation(location);
37	        burn = 0;
38	        if (rand.nextBoolean()) {
39	            gender = "M";
40	        }
41	        else {
42	            gender = "F";
43	        }
44	    }
45	    
46	    /**
47	     * Make this animal act - that is: make it do
48	     * whatever it wants/needs to do.
49	     * @param newAnimals A list to receive newly born animals.
50	     * @param step The current step.
51	     * @param weather The current weather.
52	     */
53	    abstract public void act(List<Animal> newAnimals, int step, String weather);
54	
55	    /**
56	     * Check whether the animal is alive or not.
57	     * @return true if the animal is still alive.
58	     */
59	    protected boolean isAlive()
60	    {
61	        return alive;
62	    }
63	
64	    /**
65	     * Indicate that the animal is no longer alive.
66	     * It is removed from the field.
67	     */
68	    protected void setDead()
69	    {
70	        alive = false;
71	        if(location != null) {
72	            field.clear(location);
73	            location = null;
74	            field = null;
75	        }
76	    }
77	
78	    /**
79	     * Return the animal's location.
80	     * @return The animal's location.
81	     */
82	    protected Location getLocation()
83	    {
84	        return location;
85	    }
86	    
87	    /**
88	     * Place the animal at the new location in the given field.
89	     * @param newLocation The animal's new location.
90	     */
91	    protected void setLocation(Location newLocation)
92	    {
93	        if(location != null) {
94	            field.clear(location);
95	        }
96	        location = newLocation;
97	        field.place(this, newLocation);
98	    }
99	    
100	    /**
101	     * Return the animal's field.
102	     * @return The animal's field.
103	     */
104	    protected Field getField()
105	    {
106	        return field;
107	    }
108	    
109	    /**
110	     * update the animal's burn status.
111	     * @param weather The current weather.
112	     */
113	    protected void updateBurnStatus(String weather)
114	    {
115	        if (burn > 0) {
116	            if (weather != "Rainy") {
117	                burn();
118	            }
119	            else {
120	                recover();
121	            }
122	        }
123	    }
124	    
125	    /**
126	     * animal that step on fire will get burn and if burn status > 3 the animal will die 
127	     */
128	    protected void burn()
129	    {
130	        burn++;
131	        if (burn > 3) {
132	            setDead();
133	        }
134	    }
135	    
136	    /**
137	     * if weather is rainy the animal will recover and reset it's burn status to zero.
138	     */
139	    protected void recover()
140	    {
141	        burn = 0;
142	    }
143	
144	    /**
145	     * @return the animal's gender
146	     */
147	    protected String Gender()
148	    {
149	        return gender;
150	    }
151	}
