1	import java.util.List;
2	import java.util.Iterator;
3	import java.util.Random;
4	
5	/**
6	 * A simple model of a mouse.
7	 * Mice age, move, eat seed, breed, and die.
8	 *
9	 * @version 2022.03.02 
10	 */
11	public class Mouse extends Animal
12	{
13	    // Characteristics shared by all mouses (class variables).
14	
15	    // The age at which a mouse can start to breed.
16	    private static final int BREEDING_AGE = 5;
17	    // The age to which a mouse can live.
18	    private static final int MAX_AGE = 125;
19	    // The likelihood of a mouse breeding.
20	    private static final double BREEDING_PROBABILITY = 0.25;
21	    // The likelihood of a mouse infect by disease.
22	    private static final double INFECT_PROBABILITY = 0.01;
23	    // The maximum number of births.
24	    private static final int MAX_LITTER_SIZE = 10;
25	    // The food value of a single mouse. In effect, this is the
26	    // number of steps a mouse can go.
27	    private static final int DEFAULT_FOOD_LEVEL = 5;
28	    // A shared random number generator to control breeding.
29	    private static final Random rand = Randomizer.getRandom();
30	    // The food value of a single mouse. 
31	    private static final int FOOD_VALUE = 5;
32	    
33	    // Individual characteristics (instance fields).    
34	    // The mouse's age.
35	    private int age;
36	    // The mouse's food level, which is increased by eating seed.
37	    private int foodLevel;
38	    // The mouse infected by deisease.
39	    // 0 - not infect, 1-3 degree of infection.
40	    private int infect;
41	    // chance of a mice to recover or deteriorate from disease.
42	    private static final double recover_probability = 0.3 ;
43	    private static final double deteriorate_probability = 0.15 ;
44	    /**
45	     * Create a new mouse. A mouse may be created with age
46	     * zero (a new born) or with a random age.
47	     * 
48	     * @param randomAge If true, the mouse will have a random age.
49	     * @param field The field currently occupied.
50	     * @param location The location within the field.
51	     */
52	    public Mouse(boolean randomAge, Field field, Location location)
53	    {
54	        super(field, location);
55	        if(randomAge) {
56	            age = rand.nextInt(MAX_AGE);
57	            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
58	        }
59	        else {
60	            age = 0;
61	            foodLevel = DEFAULT_FOOD_LEVEL;
62	        }
63	    }
64	    
65	    /**
66	     * This is what the mouse does most of the time - it runs 
67	     * around. Sometimes it will breed or die of old age.
68	     * @param newMice A list to return newly born mouse.
69	     * @param step The current step.
70	     * @param weather The current weather.
71	     */
72	    public void act(List<Animal> newMice, int step, String weather)
73	    {
74	        incrementAge();
75	        updateBurnStatus(weather);
76	        CheckInfectLevel();
77	        if(isAlive()) {
78	            // Infected mouse will spread the disease to other mouse.
79	            if (getInfected() != 0){
80	                Field field = getField();
81	                List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
82	                Iterator<Location> it = adjacent.iterator();
83	                while(it.hasNext()) {
84	                    Location where = it.next();
85	                    Object animal = field.getObjectAt(where);
86	                    if(animal instanceof Mouse) {
87	                        Mouse mouse = (Mouse) animal;
88	                        if(mouse.getInfected() == 0) { 
89	                            mouse.infect();
90	                            //break;
91	                        }
92	                    }
93	                }
94	                diseaseRecover();
95	            }
96	            else {
97	                giveBirth(newMice);    
98	                infect();
99	            }
100	
101	            // Move towards a source of food if found.
102	            Location newLocation = findFood();
103	
104	            if(newLocation == null) { 
105	                // No food found - try to move to a free location.
106	                newLocation = getField().freeAdjacentLocation(getLocation());
107	            }
108	
109	            if(newLocation != null) {
110	                setLocation(newLocation);
111	            }
112	            else {
113	                // Overcrowding.
114	                setDead();
115	            }       
116	        }                    
117	    }
118	
119	    /**
120	     * Increase the age.
121	     * This could result in the mouse's death.
122	     */
123	    private void incrementAge()
124	    {
125	        age++;
126	        if(age > MAX_AGE) {
127	            setDead();
128	        }
129	    }
130	    
131	    /**
132	     * Check whether or not this mouse is to give birth at this step.
133	     * New births will be made into free adjacent locations.
134	     * @param newMice A list to return newly born mouse.
135	     */
136	    private void giveBirth(List<Animal> newMice)
137	    {
138	        // New rabbits are born into adjacent locations.
139	        // Get a list of adjacent free locations.
140	        Field field = getField();
141	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
142	        int births = breed();
143	        for(int b = 0; b < births && free.size() > 0; b++) {
144	            Location loc = free.remove(0);
145	            Mouse young = new Mouse(false, field, loc);
146	            newMice.add(young);
147	        }
148	    }
149	
150	    /**
151	     * Look for grass adjacent to the current location.
152	     * Only the first seed (belong to grass) will be located.
153	     * @return Where food was found, or null if it wasn't.
154	     */
155	    private Location findFood()
156	    {
157	        Field field = getField();
158	        List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
159	        Iterator<Location> it = adjacent.iterator();
160	        while(it.hasNext()) {
161	            Location where = it.next();
162	            Object plant = field.getObjectAt(where);
163	            if(plant instanceof Grass) {
164	                Grass grass = (Grass) plant;
165	                if(grass.isAlive()) { 
166	                    foodLevel+=2;
167	                }
168	                return where;                
169	            }
170	        }
171	        return null;
172	    }
173	    
174	    /**
175	     * Generate a number representing the number of births,
176	     * if it can breed.
177	     * @return The number of births (may be zero).
178	     */
179	    private int breed()
180	    {
181	        int births = 0;
182	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
183	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
184	        }
185	        return births;
186	    }
187	
188	    /**
189	     * A mouse can breed if it has reached the breeding age.
190	     * @return true if the mouse can breed, false otherwise.
191	     */
192	    private boolean canBreed()
193	    {
194	        return age >= BREEDING_AGE;
195	    }
196	    
197	    /**
198	     * @return true if the mouse is infected by disease, false otherwise.
199	     */
200	    private int getInfected()
201	    {
202	        return infect;
203	    }
204	
205	    /**
206	     * A mouse can be infected by disease.
207	     */
208	    private void infect()
209	    {
210	        if(rand.nextDouble() <= INFECT_PROBABILITY) {
211	            infect = 1;
212	        }        
213	    }
214	    /**
215	     * mouse will die from disease when the infect indicator reach 3.
216	     */
217	    private void CheckInfectLevel()
218	    {
219	        if (infect==3){
220	                setDead();
221	            }
222	    }
223	
224	    /**
225	     * A mouse can recover or deteriorate from disease
226	     */
227	    private void diseaseRecover()
228	    {
229	        if(rand.nextDouble() <= deteriorate_probability) {
230	            infect ++ ;
231	        }  
232	        else if (rand.nextDouble() <= recover_probability) {
233	            infect -- ;
234	        }  
235	    }
236	
237	    /**
238	     * @return mouse's food value.
239	     */
240	    public int foodValue()
241	    {
242	        return FOOD_VALUE;
243	    }
244	}
