12	{
13	    // Characteristics shared by all Owls (class variables).
14	    
15	    // The age at which a Owl can start to breed.
16	    private static final int BREEDING_AGE = 5;
17	    // The age to which a owl can live.
18	    private static final int MAX_AGE = 75;
19	    // The likelihood of a owl breeding.
20	    private static final double BREEDING_PROBABILITY = 0.10;
21	    // The maximum number of births.
22	    private static final int MAX_LITTER_SIZE = 3;
23	    // The food value of a single owl. In effect, this is the
24	    // number of steps a owl can go before it has to eat again.
25	    private static final int DEFAULT_FOOD_LEVEL = 25;
26	    // A shared random number generator to control breeding.
27	    private static final Random rand = Randomizer.getRandom();
28	    // The food value of a single owl. 
29	    private static final int FOOD_VALUE = 10;
30	    
31	    // Individual characteristics (instance fields).
32	    // The Owl's age.
33	    private int age;
34	    // The Owl's food level, which is increased by eating mouse.
35	    private int foodLevel;
36	
37	    /**
38	     * Create a Owl. A Owl can be created as a new born (age zero
39	     * and not hungry) or with a random age and food level.
40	     * 
41	     * @param randomAge If true, the fox will have random age and hunger level.
42	     * @param field The field currently occupied.
43	     * @param location The location within the field.
44	     */
45	    public Owl(boolean randomAge, Field field, Location location)
46	    {
47	        super(field, location);
48	        if(randomAge) {
49	            age = rand.nextInt(MAX_AGE);
50	            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
51	        }
52	        else {
53	            age = 0;
54	            foodLevel = DEFAULT_FOOD_LEVEL;
55	        }
56	    }
57	    
58	    /**
59	     * This is what the Owl does most of the time: it hunts for
60	     * mouses. In the process, it might breed, die of hunger,
61	     * or die of old age.
62	     * @param newOwls A list to return newly born owls.
63	     * @param step The current step.
64	     * @param weather The current weather.
65	     */
66	    public void act(List<Animal> newOwls, int step, String weather)
67	    {
68	        incrementAge();
69	        incrementHunger();
70	        updateBurnStatus(weather);
71	        if(isAlive()) {
72	            giveBirth(newOwls);            
73	            // Move towards a source of food if found.
74	            Location newLocation = findFood();
75	            if(newLocation == null) { 
76	                // No food found - try to move to a free location.
77	                newLocation = getField().freeAdjacentLocation(getLocation());
78	            }
79	            // See if it was possible to move.
80	            if(newLocation != null) {
81	                setLocation(newLocation);
82	            }
83	            else {
84	                // Overcrowding.
85	                setDead();
86	            }
87	        }
88	    }
89	
90	    /**
91	     * Increase the age. This could result in the Owl's death.
92	     */
93	    private void incrementAge()
94	    {
95	        age++;
96	        if(age > MAX_AGE) {
97	            setDead();
98	        }
99	    }
100	    
101	    /**
102	     * Make this owl more hungry. This could result in the Owl's death.
103	     */
104	    private void incrementHunger()
105	    {
106	        foodLevel--;
107	        if(foodLevel <= 0) {
108	            setDead();
109	        }
110	    }
111	    
112	    /**
113	     * Look for mouses adjacent to the current location.
114	     * Only the first live mouse is eaten.
115	     * @return Where food was found, or null if it wasn't.
116	     */
117	    private Location findFood()
118	    {
119	        Field field = getField();
120	        List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
121	        Iterator<Location> it = adjacent.iterator();
122	        while(it.hasNext()) {
123	            Location where = it.next();
124	            Object animal = field.getObjectAt(where);
125	            if(animal instanceof Mouse) {
126	                Mouse mouse = (Mouse) animal;
127	                if(mouse.isAlive()) { 
128	                    mouse.setDead();
129	                    foodLevel = foodLevel + mouse.foodValue();
130	                    return where;
131	                }
132	            }
133	        }
134	        return null;
135	    }
