138	     * Check whether or not this Owl is to give birth at this step.
139	     * New births will be made into free adjacent locations.
140	     * @param newOwls A list to return newly born owls.
141	     */
142	    private void giveBirth(List<Animal> newOwls)
143	    {
144	        // New Owls are born into adjacent locations.
145	        // Get a list of adjacent free locations.
146	        Field field = getField();
147	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
148	        int births = breed();
149	        for(int b = 0; b < births && free.size() > 0; b++) {
150	            Location loc = free.remove(0);
151	            Owl young = new Owl(false, field, loc);
152	            newOwls.add(young);
153	        }
154	    }
155	        
156	    /**
157	     * Generate a number representing the number of births,
158	     * if it can breed.
159	     * @return The number of births (may be zero).
160	     */
161	    private int breed()
162	    {
163	        int births = 0;
164	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
165	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
166	        }
167	        return births;
168	    }
169	
170	    /**
171	     * A Owl can breed if it has reached the breeding age.
172	     * @return true if the owl can breed.
173	     */
174	    private boolean canBreed()
175	    {
176	        return age >= BREEDING_AGE;
177	    }
178	
179	    /**
180	     * @return owl's food value.
181	     */
182	    public int foodValue()
183	    {
184	        return FOOD_VALUE;
185	    }
186	}
