11	public class Deer extends Animal
12	{
13	    // Characteristics shared by all Deers (class variables).
14	
15	    // The age at which a Deer can start to breed.
16	    private static final int BREEDING_AGE = 10;
17	    // The age to which a Deer can live.
18	    private static final int MAX_AGE = 175;
19	    // The likelihood of a Deer breeding.
20	    private static final double BREEDING_PROBABILITY = 0.10;
21	    // The maximum number of births.
22	    private static final int MAX_LITTER_SIZE = 5;
23	    // A shared random number generator to control breeding.
24	    private static final Random rand = Randomizer.getRandom();
25	    // The food value of a single dear. In effect, this is the
26	    // number of steps it can go.
27	    private static final int FOOD_VALUE = 50;
28	    // The default food value of a single deer.
29	    private static final int DEFAULT_FOOD_LEVEL = 250;
30	    
31	    // Individual characteristics (instance fields).    
32	    // The Deer's age.
33	    private int age;
34	    // The Deer's food level, which is increased by eating grass.
35	    private int foodLevel;
36	
37	    /**
38	     * Create a new Deer. A Deer may be created with age
39	     * zero (a new born) or with a random age.
40	     * 
41	     * @param randomAge If true, the Deer will have a random age.
42	     * @param field The field currently occupied.
43	     * @param location The location within the field.
44	     */
45	    public Deer(boolean randomAge, Field field, Location location)
46	    {
47	        super(field, location);
48	        if(randomAge) {
49	            age = rand.nextInt(MAX_AGE);
50	            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
51	        }
52	        else {
53	            age = 0;
54	            foodLevel = DEFAULT_FOOD_LEVEL;
55	        }
56	    }
57	    
58	    /**
59	     * This is what the Deer does most of the time - it runs 
60	     * around. Sometimes it will breed or die of old age.
61	     * @param newDeers A list to return newly born Deers.
62	     * @param step The current step
63	     * @param weather The current weather.
64	     */
65	    public void act(List<Animal> newDeers, int step, String weather)
66	    {
67	        incrementAge();
68	        incrementHunger();
69	        updateBurnStatus(weather);
70	        if(isAlive()) {
71	            giveBirth(newDeers);  
72	           
73	            // Move towards a source of food if found.
74	            Location newLocation;
75	            if (weather == "RAINY") {
76	                newLocation = null;
77	            }
78	            else {
79	                newLocation = findFood();
80	            }
81	
82	            if(newLocation == null) { 
83	                // No food found - try to move to a free location.
84	                newLocation = getField().freeAdjacentLocation(getLocation());
85	            }
86	
87	            // See if it was possible to move.            
88	            if(newLocation != null) {
89	                setLocation(newLocation);
90	            }
91	            else {
92	                // Overcrowding.
93	                setDead();
94	            }
95	        }
96	    }
97	
98	    /**
99	     * Increase the age.
100	     * This could result in the Deer's death.
101	     */
102	    private void incrementAge()
103	    {
104	        age++;
105	        if(age > MAX_AGE) {
106	            setDead();
107	        }
108	    }
109	    
110	    /**
111	     * Check whether or not this Deer is to give birth at this step.
112	     * New births will be made into free adjacent locations.
113	     * @param newDeers A list to return newly born Deers.
114	     */
115	    private void giveBirth(List<Animal> newDeers)
116	    {
117	
118	        boolean breedingPair = false;
119	        Field field = getField();
120	        List<Location> adjacent = field.adjacentLocations(getLocation(), 2);
121	        Iterator<Location> it = adjacent.iterator();
122	        while(it.hasNext()) {
123	            Location where = it.next();
124	            Object animal = field.getObjectAt(where);
125	            if(animal instanceof Deer) {
126	                Deer deer = (Deer) animal;
127	                if(deer.Gender() != Gender()) { 
128	                    breedingPair = true;
129	                    break;
130	                }
131	            }
132	        }
133	
134	        // New Deers are born into adjacent locations.
135	        // Get a list of adjacent free locations.
136	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
137	        int births = breed();
138	        for(int b = 0; b < births && free.size() > 0 && breedingPair; b++) {
139	            Location loc = free.remove(0);
140	            Deer young = new Deer(false, field, loc);
141	            newDeers.add(young);
142	        }
143	    }
144	        
145	    /**
146	     * Generate a number representing the number of births,
147	     * if it can breed.
148	     * @return The number of births (may be zero).
149	     */
150	    private int breed()
151	    {
152	        int births = 0;
153	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
154	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
155	        }
156	        return births;
157	    }
