171	     * Look for grass adjacent to the current location.
172	     * Only the first live grass is eaten.
173	     * @return Where food was found, or null if it wasn't.
174	     */
175	    private Location findFood()
176	    {
177	        Field field = getField();
178	        List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
179	        Iterator<Location> it = adjacent.iterator();
180	        while(it.hasNext()) {
181	            Location where = it.next();
182	            Object plant = field.getObjectAt(where);
183	            if(plant instanceof Grass) {
184	                Grass grass = (Grass) plant;
185	                if(grass.isAlive()) { 
186	                    if (grass.getSize()>12 && foodLevel<30){
187	                        grass.decrementSize();
188	                        foodLevel+=20;
189	                    }
190	                    return where;
191	                }
192	            }
193	        }
194	        return null;
195	    }
196	    
197	    /**
198	     * A Deer can breed if it has reached the breeding age.
199	     * @return true if the Deer can breed, false otherwise.
200	     */
201	    private boolean canBreed()
202	    {
203	        return age >= BREEDING_AGE;
204	    }
205	
206	
207	    /**
208	     * @return deer's food value.
209	     */
210	    public int foodValue()
211	    {
212	        return FOOD_VALUE;
213	    }
