5	/**
6	 * A simple model of a Grass.
7	 * Deers age, move, breed, and die.
8	 *
9	 * @version 2022.03.02 
10	 */
11	public class Grass extends Plant
12	{
13	    // Characteristics shared by all Grass (class variables).
14	
15	    // The age to which a Grass can live.
16	    private static final int MAX_SIZE = 50;
17	    // The maximum grow rate.
18	    private static final int MAX_GROW_RATE = 20;
19	    // The likelihood of grass get steppe fire.
20	    private static final double STEPPE_FIRE_PROBABILITY = 0.02;
21	    // A shared random number generator to control breeding.
22	    private static final Random rand = Randomizer.getRandom();
23	    
24	    // Individual characteristics (instance fields).
25	    
26	    // The Grass's age.
27	    private int size;
28	    // The Grass's steppe fire status
29	    private boolean steppeFired;
30	
31	    /**
32	     * Create a new Grass. A Grass may be created with size
33	     * 50 or with a random size.
34	     * 
35	     * @param randomSize If true, the Grass will have a random size.
36	     * @param field The field currently occupied.
37	     * @param location The location within the field.
38	     */
39	    public Grass(boolean randomSize, Field field, Location location)
40	    {
41	        super(field, location);
42	        
43	        if(randomSize) {
44	            size = rand.nextInt(MAX_SIZE);
45	        }
46	        else {
47	            size = 50;
48	        }
49	        steppeFired = false;
50	    }
51	    
52	    /**
53	     * This is what the Grass does most of the time - it grows 
54	     * around. Sometimes it will breed or die of steppeFire. If
55	     * the grass catches fire, it will also burn the unit adjacent to it 
56	     * @param step The current step
57	     * @param weather The current weather.
58	     */
59	    public void act( int step, String weather)
60	    {
61	        if(isAlive()) {
62	            if(weather == "Rainy") {
63	                incrementSize();
64	                steppeFired = false;
65	            }
66	            else {
67	                getSteppeFire();
68	                if (steppeFire()==true && getLocation() != null) {                
69	                    Field field = getField();
70	                    List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
71	                    Iterator<Location> it = adjacent.iterator();
72	                    while(it.hasNext()) {
73	                        Location where = it.next();
74	                        Object creature = field.getObjectAt(where);
75	                        if(creature instanceof Grass) {
76	                            Grass grass = (Grass) creature;
77	                            grass.getSteppeFire();                        
78	                        }
79	                        if(creature instanceof Animal) {
80	                            Animal animal = (Animal) creature;
81	                            animal.burn();                        
82	                        }
83	                    }
84	            
85	                    decrementSize();                
86	                }
87	            }
88	        }
89	    }
90	
91	    /**
92	     * Increase the size.
93	     */
94	    private void incrementSize()
95	    {
96	        size = size + rand.nextInt(MAX_GROW_RATE)+20;
97	        if(size > MAX_SIZE) {
98	            size = MAX_SIZE;
99	        }
100	    }
101	    
102	    /**
103	     * Decrease the size.
104	     */
105	    public void decrementSize()
106	    {
107	        size = size -1;
108	        if(size == 0) {
109	            setDead();
110	        }
111	    }
112	
113	    /**
114	     * Grass can become steppe fire.
115	     */
116	    private void getSteppeFire()
117	    {
118	        if(rand.nextDouble() <= STEPPE_FIRE_PROBABILITY) {
119	            steppeFired = true;
120	        }        
121	    }
122	
123	    /**
124	     * Return steppe fire status.
125	     * @return true if the grass become steppe fire, false otherwise.
126	     */
127	    public boolean steppeFire()
128	    {
129	        return steppeFired;
130	    }
131	
132	    /**
133	     * Return size status.
134	     * @return size The current size of the grass.
135	     */
136	    public int getSize()
