1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	
7	/**
8	 * A simple predator-prey simulator, based on a rectangular field
9	 * containing rabbits and foxes.
10	 *
11	 * @version 2022.02.xx 
12	 */
13	public class Simulator
14	{
15	    // Constants representing configuration information for the simulation.
16	    // The default width for the grid. 
17	    private static final int DEFAULT_WIDTH = 120;
18	    // The default depth of the grid. 
19	    private static final int DEFAULT_DEPTH = 80;
20	    // The probability that a fox will be created in any given grid position.
21	    private static final double LION_CREATION_PROBABILITY = 0.01;
22	    // The probability that a rabbit will be created in any given grid position.
23	    private static final double DEER_CREATION_PROBABILITY = 0.02;    
24	    // The probability that a owl will be created in any given grid position.
25	    private static final double OWL_CREATION_PROBABILITY = 0.05;
26	    // The probability that a cat will be created in any given grid position.
27	    private static final double CAT_CREATION_PROBABILITY = 0.05;
28	    // The probability that a mouse will be created in any given grid position.
29	    private static final double MOUSE_CREATION_PROBABILITY = 0.04;    
30	    // The probability that a grass will be created in any given grid position.
31	    private static final double GRASS_CREATION_PROBABILITY = 0.4;    
32	
33	    // List of animals in the field.
34	    private List<Animal> animals;
35	    // List of animals in the field.
36	    private List<Plant> plants;
37	    // The current state of the field.
38	    private Field field;
39	    // The current step of the simulation.
40	    private int step;
41	    // The current weather of the simulation.
42	    private String weather;
43	    // A graphical view of the simulation.
44	    private SimulatorView view;
45	    
46	    /**
47	     * Construct a simulation field with default size.
48	     */
49	    public Simulator()
50	    {
51	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
52	    }
53	    
54	    /**
55	     * Create a simulation field with the given size.
56	     * @param depth Depth of the field. Must be greater than zero.
57	     * @param width Width of the field. Must be greater than zero.
58	     */
59	    public Simulator(int depth, int width)
60	    {
61	        if(width <= 0 || depth <= 0) {
62	            System.out.println("The dimensions must be greater than zero.");
63	            System.out.println("Using default values.");
64	            depth = DEFAULT_DEPTH;
65	            width = DEFAULT_WIDTH;
66	        }
67	        
68	        animals = new ArrayList<>();
69	        plants = new ArrayList<>();
70	        field = new Field(depth, width);
71	
72	        // Create a view of the state of each location in the field.
73	        view = new SimulatorView(depth, width);
74	        view.setColor(Deer.class, Color.BLUE);
75	        view.setColor(Lion.class, Color.RED);
76	        view.setColor(Mouse.class, Color.YELLOW);
77	        view.setColor(Owl.class, Color.ORANGE);
78	        view.setColor(Cat.class, Color.PINK);
79	        view.setColor(Grass.class, Color.GREEN);
80	        
81	        // Setup a valid starting point.
82	        reset();
83	    }
84	    
85	    /**
86	     * Run the simulation from its current state for a reasonably long period,
87	     * (4000 steps).
88	     */
89	    public void runLongSimulation()
90	    {
91	        simulate(4000);
92	    }
93	    
94	    /**
95	     * Run the simulation from its current state for the given number of steps.
96	     * Stop before the given number of steps if it ceases to be viable.
97	     * @param numSteps The number of steps to run for.
98	     */
99	    public void simulate(int numSteps)
100	    {
101	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
102	            simulateOneStep();
103	            delay(60);   // uncomment this to run more slowly
104	        }
105	    }
106	    
107	    /**
108	     * Run the simulation from its current state for a single step.
109	     * Iterate over the whole field updating the state of each
110	     * fox and rabbit.
111	     */
112	    public void simulateOneStep()
113	    {
114	        step++;
115	        sim_weather();
116	        
117	        // Provide space for newborn animals.
118	        List<Animal> newAnimals = new ArrayList<>();        
119	        // Let all animals act.
120	        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
121	            Animal animal = it.next();
122	            animal.act(newAnimals, step, weather);
123	            if(! animal.isAlive()) {
124	                it.remove();
125	            }
126	        }
127	               
128	        // Add the newly born foxes and rabbits to the main lists.
129	        animals.addAll(newAnimals);
130	
131	        // Let all plants act.
132	        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
133	            Plant plant = it.next();
134	            plant.act(step, weather);
135	            if(! plant.isAlive()) {
136	                it.remove();
137	            }
138	        }
139	        
140	        view.showStatus(step, field, weather);
141	    }
142	        
143	    /**
144	     * Reset the simulation to a starting position.
145	     */
146	    public void reset()
147	    {
148	        step = 0;
149	        animals.clear();
150	        plants.clear();
151	        populate();
152	        sim_weather();
153	        
154	        // Show the starting state in the view.
155	        view.showStatus(step, field, weather);
156	    }
157	    
158	    /**
159	     * Randomly populate the field with Lions, Cats, Owls, Deers and mouses.
160	     */
161	    private void populate()
162	    {
163	        Random rand = Randomizer.getRandom();
164	        field.clear();
165	        for(int row = 0; row < field.getDepth(); row++) {
166	            for(int col = 0; col < field.getWidth(); col++) {
167	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
168	                    Location location = new Location(row, col);
169	                    Lion lion = new Lion(true, field, location);
170	                    animals.add(lion);
171	                }
172	                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
173	                    Location location = new Location(row, col);
174	                    Deer deer = new Deer(true, field, location);
175	                    animals.add(deer);
176	                }
177	                else if(rand.nextDouble() <= OWL_CREATION_PROBABILITY) {
178	                    Location location = new Location(row, col);
179	                    Owl owl = new Owl(true, field, location);
180	                    animals.add(owl);
181	                }
182	                else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
183	                    Location location = new Location(row, col);
184	                    Mouse mouse = new Mouse(true, field, location);
185	                    animals.add(mouse);
186	                }
187	                else if(rand.nextDouble() <= CAT_CREATION_PROBABILITY) {
188	                    Location location = new Location(row, col);
189	                    Cat cat = new Cat(true, field, location);
190	                    animals.add(cat);
191	                }
192	                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
193	                    Location location = new Location(row, col);
194	                    Grass grass = new Grass(true, field, location);
195	                    plants.add(grass);
196	                }
197	                // else leave the location empty.
198	            }
199	        }
200	    }
201	    
202	    /**
203	     * Pause for a given time.
204	     * @param millisec  The time to pause for, in milliseconds
205	     */
206	    private void delay(int millisec)
207	    {
208	        try {
209	            Thread.sleep(millisec);
210	        }
211	        catch (InterruptedException ie) {
212	            // wake up
213	        }
214	    }
215	
216	    /**
217	     * 
218	     * 
219	     */
220	    private void sim_weather()
221	    {
222	        Random rand = Randomizer.getRandom();
223	        if(rand.nextDouble() <= 0.33) {
224	            weather = "Foggy";
225	        }
226	        else if (rand.nextDouble() <= 0.33) {
227	            weather = "Rainy";
228	        }
229	        else {
230	            weather = "Sunny";
231	        }
232	    }
233	
234	    /**
235	     * 
236	     * 
237	     */
238	    private String get_weather()
239	    {
240	        return weather;
241	    }
242	}
