162	     * a nested class (a class defined inside a class) which
163	     * defines a custom component for the user interface. This
164	     * component displays the field.
165	     * This is rather advanced GUI stuff - you can ignore this 
166	     * for your project if you like.
167	     */
168	    private class FieldView extends JPanel
169	    {
170	        private final int GRID_VIEW_SCALING_FACTOR = 20;
171	
172	        private int gridWidth, gridHeight;
173	        private int xScale, yScale;
174	        Dimension size;
175	        private Graphics g;
176	        private Image fieldImage;
177	
178	        /**
179	         * Create a new FieldView component.
180	         */
181	        public FieldView(int height, int width)
182	        {
183	            gridHeight = height;
184	            gridWidth = width;
185	            size = new Dimension(0, 0);
186	        }
187	
188	        /**
189	         * Tell the GUI manager how big we would like to be.
190	         */
191	        public Dimension getPreferredSize()
192	        {
193	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
194	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
195	        }
196	
197	        /**
198	         * Prepare for a new round of painting. Since the component
199	         * may be resized, compute the scaling factor again.
200	         */
201	        public void preparePaint()
202	        {
203	            if(! size.equals(getSize())) {  // if the size has changed...
204	                size = getSize();
205	                fieldImage = fieldView.createImage(size.width, size.height);
206	                g = fieldImage.getGraphics();
207	
208	                xScale = size.width / gridWidth;
209	                if(xScale < 1) {
210	                    xScale = GRID_VIEW_SCALING_FACTOR;
211	                }
212	                yScale = size.height / gridHeight;
213	                if(yScale < 1) {
214	                    yScale = GRID_VIEW_SCALING_FACTOR;
215	                }
216	            }
217	        }
218	        
219	        /**
220	         * Paint on grid location on this field in a given color.
221	         */
222	        public void drawMark(int x, int y, Color color)
223	        {
224	            g.setColor(color);
225	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
226	        }
227	
228	        /**
229	         * The field view component needs to be redisplayed. Copy the
230	         * internal image to screen.
231	         */
232	        public void paintComponent(Graphics g)
233	        {
234	            if(fieldImage != null) {
235	                Dimension currentSize = getSize();
236	                if(size.equals(currentSize)) {
237	                    g.drawImage(fieldImage, 0, 0, null);
238	                }
239	                else {
