4	/**
5	 * This class collects and provides some statistical data on the state 
6	 * of a field. It is flexible: it will create and maintain a counter 
7	 * for any class of object that is found within the field.
8	 *
9	 * @version 2016.02.29
10	 */
11	public class FieldStats
12	{
13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
14	    private HashMap<Class, Counter> counters;
15	    // Whether the counters are currently up to date.
16	    private boolean countsValid;
17	
18	    /**
19	     * Construct a FieldStats object.
20	     */
21	    public FieldStats()
22	    {
23	        // Set up a collection for counters for each type of animal that
24	        // we might find
25	        counters = new HashMap<>();
26	        countsValid = true;
27	    }
28	
29	    /**
30	     * Get details of what is in the field.
31	     * @return A string describing what is in the field.
32	     */
33	    public String getPopulationDetails(Field field)
34	    {
35	        StringBuffer buffer = new StringBuffer();
36	        if(!countsValid) {
37	            generateCounts(field);
38	        }
39	        for(Class key : counters.keySet()) {
40	            Counter info = counters.get(key);
41	            buffer.append(info.getName());
42	            buffer.append(": ");
43	            buffer.append(info.getCount());
44	            buffer.append(' ');
45	        }
46	        return buffer.toString();
47	    }
48	    
49	    /**
50	     * Invalidate the current set of statistics; reset all 
51	     * counts to zero.
52	     */
53	    public void reset()
54	    {
55	        countsValid = false;
56	        for(Class key : counters.keySet()) {
57	            Counter count = counters.get(key);
58	            count.reset();
59	        }
60	    }
61	
62	    /**
63	     * Increment the count for one class of animal.
64	     * @param animalClass The class of animal to increment.
65	     */
66	    public void incrementCount(Class animalClass)
67	    {
68	        Counter count = counters.get(animalClass);
69	        if(count == null) {
70	            // We do not have a counter for this species yet.
71	            // Create one.
72	            count = new Counter(animalClass.getName());
73	            counters.put(animalClass, count);
74	        }
75	        count.increment();
76	    }
77	
78	    /**
79	     * Indicate that an animal count has been completed.
80	     */
81	    public void countFinished()
82	    {
83	        countsValid = true;
84	    }
85	
86	    /**
87	     * Determine whether the simulation is still viable.
88	     * I.e., should it continue to run.
89	     * @return true If there is more than one species alive.
90	     */
91	    public boolean isViable(Field field)
92	    {
93	        // How many counts are non-zero.
94	        int nonZero = 0;
95	        if(!countsValid) {
96	            generateCounts(field);
97	        }
98	        for(Class key : counters.keySet()) {
99	            Counter info = counters.get(key);
100	            if(info.getCount() > 0 && info.getName() != "Grass") {
101	                nonZero++;
102	            }
103	        }
104	        return nonZero > 1;
105	    }
106	    
107	    /**
108	     * Generate counts of the number of animals.
109	     * These are not kept up to date as animals
110	     * are placed in the field, but only when a request
111	     * is made for the information.
112	     * @param field The field to generate the stats for.
113	     */
114	    private void generateCounts(Field field)
115	    {
116	        reset();
117	        for(int row = 0; row < field.getDepth(); row++) {
118	            for(int col = 0; col < field.getWidth(); col++) {
119	                Object animal = field.getObjectAt(row, col);
120	                if(animal != null) {
121	                    incrementCount(animal.getClass());
122	                }
123	            }
124	        }
125	        countsValid = true;
126	    }
127	}
